package vn.edu.crs.registrationservice.config;
import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import vn.edu.crs.registrationservice.security.JwtAuthFilter;
@Configuration @RequiredArgsConstructor public class SecurityConfig {private final JwtAuthFilter jwt; @Bean SecurityFilterChain filterChain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((request,response,error)->response.setStatus(401)).accessDeniedHandler((request,response,error)->response.setStatus(403))).authorizeHttpRequests(a->a.requestMatchers("/registrations/**").authenticated().anyRequest().permitAll()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}}
